"""Editorial source for the Faro training production handbook (Persian)."""

SCENARIOS = []

def add(title, publish, module, goal, role, route, prerequisite, data, steps,
        hook, result, ending, risks, sources, duration=60, level='ساده', priority='P1'):
    SCENARIOS.append(dict(id=f'V{len(SCENARIOS)+1:02}', title=title, publish=publish,
        module=module, goal=goal, role=role, route=route, prerequisite=prerequisite,
        data=data, steps=steps, hook=hook, result=result, ending=ending, risks=risks,
        sources=sources, duration=duration, level=level, priority=priority))

